import java.util.ArrayList;

public class PrefixSum {

    public static ArrayList<Integer> prefSum(int[] arr) {
        int n = arr.length;

        ArrayList<Integer> prefixSum = new ArrayList<>();

        prefixSum.add(arr[0]);

        for (int i = 1; i < n; i++)
            prefixSum.add(prefixSum.get(i - 1) + arr[i]);

        return prefixSum;
    }

    public static void main(String[] args) {
        int[] arr = {10, 20, 10, 5, 15};
        ArrayList<Integer> prefixSum = prefSum(arr);
        for (int i : prefixSum) {
            System.out.print(i + " ");
        }
    }
}

import java.util.ArrayList;
import java.util.List;

public final class PrefixSum {

    private PrefixSum() {
    }

    public static List<Integer> build(int[] values) {
        List<Integer> prefixSums = new ArrayList<>();
        int runningTotal = 0;

        for (int value : values) {
            runningTotal += value;
            prefixSums.add(runningTotal);
        }

        return prefixSums;
    }

    public static void main(String[] args) {
        int[] values = {10, 20, 10, 5, 15};
        List<Integer> prefixSums = build(values);

        for (int prefixSum : prefixSums) {
            System.out.print(prefixSum + " ");
        }
    }
}

